private static ArtifactScope scope(Map<String, ?> values) {
    Object host = values.get("hostId");
    return new ArtifactScope(host == null ? "local-host" : requiredScopeText(host, "hostId"),
            requiredScopeText(values.get("workspaceId"), "workspaceId"),
            requiredScopeText(values.get("sessionId"), "sessionId"));
}

private static String requiredScopeText(Object value, String name) {
    if (value == null || String.valueOf(value).isBlank()) throw invalid("missing_" + name);
    return String.valueOf(value);
}

